import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';

/**
 * DRAFT when added; DRAFT → OPEN → SETTLED, and DRAFT, OPEN or PENDING → VOID. A clerk settling a claim
 * above the clerk limit sends it PENDING; a steward approves it (SETTLED) or rejects it (OPEN again).
 */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A move of a claim's status: open, settle, approve, reject or void. */
export type ClaimAction = 'open' | 'settle' | 'approve' | 'reject' | 'void';

/** Whether a claim is open: OPEN, or PENDING a steward's approval. */
export function isOpen(claim: ClaimView): boolean {
  return claim.status === 'OPEN' || claim.status === 'PENDING';
}

export interface ClaimView {
  id: number;
  personId: number;
  /** The amount with two decimals, e.g. "10.25". */
  amount: string;
  /** yyyy-mm-dd */
  date: string;
  note: string;
  status: ClaimStatus;
  /**
   * The number given when the claim was opened: sheet-wide (e.g. "3"), or under period numbering
   * within its period (e.g. "P1-2", or "X-1" in no period); null while DRAFT, and kept once VOID.
   */
  number: string | null;
  /**
   * The due fixed when the claim was settled, with two decimals; null when it is not fixed (not
   * settled, or the grade had no rate then), so its due follows the current rate.
   */
  settledDue: string | null;
  /** The user who opened the claim; null until it is opened. The opener cannot settle it. */
  openedBy: string | null;
  /** Whether the claim is bound by its person's last statement to the figure it had then. */
  stated: boolean;
  /** The figure the statement bound the claim to, with two decimals; null when unbound, or when it was n/a. */
  statedDue: string | null;
  /** The number of the SETTLED claim this one corrects; null unless it is a correction. */
  corrects: string | null;
}

/** Whether a claim is a correction: its amount is below 0.00. It has no floor and no late charge. */
export function isCorrection(claim: ClaimView): boolean {
  return claim.amount.startsWith('-') && cents(claim.amount) !== 0;
}

/** Whether a claim counts toward what is claimed and due: only OPEN, PENDING and SETTLED claims do. */
export function counts(claim: ClaimView): boolean {
  return isOpen(claim) || claim.status === 'SETTLED';
}

/** A claim's due-by (yyyy-mm-dd): its date plus the sheet's terms in days. */
export function dueBy(claim: ClaimView, terms: number): string {
  const [y, m, d] = claim.date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + terms)).toISOString().slice(0, 10);
}

/** Whether a claim is overdue: it is OPEN or PENDING and its due-by is before the sheet's today. */
export function overdue(claim: ClaimView, terms: number, today: string): boolean {
  return isOpen(claim) && today !== '' && dueBy(claim, terms) < today;
}

/** What a late charge is worked from: the sheet's late percent, terms and today. */
export interface LateTerms {
  /** The late percent with two decimals. */
  pct: string;
  terms: number;
  /** The sheet's today (yyyy-mm-dd); empty when none is loaded. */
  today: string;
}

/**
 * Whether a claim's live figures round half up (else half to even): when the date it rounds by is
 * before the policy date, or the sheet's today when no policy date is set. A correction rounds by the
 * date of the claim it corrects, found by number among its person's claims (its own when not found).
 */
export function roundsHalfUp(claim: ClaimView, claims: ClaimView[], policyDate: string, today: string): boolean {
  const corrected = claim.corrects === null
    ? undefined
    : claims.find((c) => c.personId === claim.personId && c.number === claim.corrects);
  const date = corrected?.date ?? claim.date;
  const policy = policyDate || today;
  return policy !== '' && date < policy;
}

/** How many full 30 days an overdue claim is past its due-by on the sheet's today; 0 when not overdue. */
export function latePeriods(claim: ClaimView, late: LateTerms): number {
  if (!overdue(claim, late.terms, late.today)) return 0;
  const days = (Date.parse(late.today) - Date.parse(dueBy(claim, late.terms))) / 86_400_000;
  return Math.floor(days / 30);
}

/** What a bulk open did: the claims opened, as they are now, and how many were refused. */
export interface BulkOpenView {
  opened: ClaimView[];
  refused: number;
}

export interface ClaimForm {
  amount: string;
  /** Empty means the sheet's today (or, on an edit, the claim's own date). */
  date: string | null;
  note: string;
  /** The number of the claim a correction corrects; null on any other claim. */
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';

/** The roles a user name can have on a sheet; a name with none set is a clerk. */
export const ROLES = ['clerk', 'steward'] as const;
export type RoleName = (typeof ROLES)[number];

export interface RoleView {
  user: string;
  role: RoleName;
}

export interface SettingsView {
  /** The clerk limit with two decimals, e.g. "1.50"; null when there is no limit. */
  clerkLimit: string | null;
  /** The floor with two decimals, e.g. "1.00": a claim's live due is at least it. */
  floor: string;
  /** The terms in days: a claim is due by its date plus them. */
  terms: number;
  /** The late percent with two decimals, e.g. "10.00": an overdue claim gains it of its figure every full 30 days. */
  latePct: string;
  /** The policy date (yyyy-mm-dd); null when blank (the sheet's today is then the policy date). */
  policyDate: string | null;
  /** Period numbering from (yyyy-mm-dd): claims opened on or after it are numbered within their period; null when off. */
  periodNumberingFrom: string | null;
}

/** A clerk limit as the form takes it: up to two decimals, or blank for no limit. */
export const LIMIT = /^(\d{1,12}(\.\d{1,2})?)?$/;

/** A floor as the form takes it: 0.00 or more, with up to two decimals. */
export const FLOOR = /^\d{1,12}(\.\d{1,2})?$/;

/** A late percent as the form takes it: 0.00 or more, with up to two decimals. */
export const LATE_PCT = /^\d{1,3}(\.\d{1,2})?$/;

/** A policy date as the form takes it: yyyy-mm-dd, or blank for the sheet's today. */
export const POLICY_DATE = /^(\d{4}-\d{2}-\d{2})?$/;

/** A period-numbering-from date as the form takes it: yyyy-mm-dd, or blank for off. */
export const PERIOD_NUMBERING_FROM = /^(\d{4}-\d{2}-\d{2})?$/;

/** Terms as the form takes them: a whole number of days. */
export const TERMS = /^\d{1,4}$/;

// The sheet's settings and the roles its user names have, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class SettingsApi {
  private readonly http = inject(HttpClient);

  get(sheet: string): Promise<SettingsView> {
    return firstValueFrom(this.http.get<SettingsView>(`${this.url(sheet)}/settings`));
  }

  /** Set the clerk limit; a blank value means no limit. */
  setClerkLimit(sheet: string, value: string): Promise<SettingsView> {
    return firstValueFrom(this.http.put<SettingsView>(`${this.url(sheet)}/settings/clerk-limit`, { value }));
  }

  /** Set the floor. */
  setFloor(sheet: string, value: string): Promise<SettingsView> {
    return firstValueFrom(this.http.put<SettingsView>(`${this.url(sheet)}/settings/floor`, { value }));
  }

  /** Set the terms, in days. */
  setTerms(sheet: string, value: string): Promise<SettingsView> {
    return firstValueFrom(this.http.put<SettingsView>(`${this.url(sheet)}/settings/terms`, { value }));
  }

  /** Set the late percent. */
  setLatePct(sheet: string, value: string): Promise<SettingsView> {
    return firstValueFrom(this.http.put<SettingsView>(`${this.url(sheet)}/settings/late-pct`, { value }));
  }

  /** Set the policy date; a blank value means the sheet's today. */
  setPolicyDate(sheet: string, value: string): Promise<SettingsView> {
    return firstValueFrom(this.http.put<SettingsView>(`${this.url(sheet)}/settings/policy-date`, { value }));
  }

  /** Set the period-numbering-from date; a blank value turns period numbering off. */
  setPeriodNumberingFrom(sheet: string, value: string): Promise<SettingsView> {
    return firstValueFrom(this.http.put<SettingsView>(`${this.url(sheet)}/settings/period-numbering-from`, { value }));
  }

  /** The roles set on the sheet, by user name. */
  roles(sheet: string): Promise<RoleView[]> {
    return firstValueFrom(this.http.get<RoleView[]>(`${this.url(sheet)}/roles`));
  }

  /** Set a user name's role on the sheet. */
  setRole(sheet: string, form: RoleView): Promise<RoleView> {
    return firstValueFrom(this.http.put<RoleView>(`${this.url(sheet)}/roles`, form));
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}`;
  }
}
import { Component, effect, inject, signal, untracked } from '@angular/core';
import { FLOOR, LATE_PCT, LIMIT, PERIOD_NUMBERING_FROM, POLICY_DATE, ROLES, TERMS, RoleName, RoleView, SettingsApi } from '../../core/settings';
import { Session } from '../../core/session';

// The sheet's settings (the clerk limit, the floor, the terms, the late percent, the policy date and period numbering from) and the roles user names have on it (clerk by default,
// or steward), each changed through its own form.
@Component({
  selector: 'app-settings',
  template: `
    <section aria-labelledby="settings-heading">
      <h2 id="settings-heading">Settings</h2>
      <form (submit)="saveSettings($event)" aria-label="Change settings">
        <label for="setting-clerk-limit">Clerk limit (empty: no limit)</label>
        <input
          id="setting-clerk-limit"
          data-testid="setting-clerk-limit"
          inputmode="decimal"
          [value]="limit()"
          (input)="limit.set(value($event)); limitEdited = true; settingsError.set(null)"
        />
        <label for="setting-floor">Floor</label>
