  }

  /** Set the floor. */
  setFloor(sheet: string, value: string): Promise<SettingsView> {
    return firstValueFrom(this.http.put<SettingsView>(`${this.url(sheet)}/settings/floor`, { value }));
  }

  /** Set the terms, in days. */
